/* =============================================================
   INVOICEFORGE — script.js
   A fully offline, Local-Storage-backed invoicing SPA.
   No frameworks, no backend. Vanilla ES6 only.
   ============================================================= */

'use strict';

/* ---------------------------------------------------------------
   0. CONSTANTS & DEFAULTS
   --------------------------------------------------------------- */
