function iconTrash() { return '<svg viewBox="0 0 24 24" width="15" height="15"><path fill="currentColor" d="M6 7h12l-1 14H7L6 7zm3-4h6l1 2h4v2H2V5h4l1-2z"/></svg>'; }
function iconCopy() { return '<svg viewBox="0 0 24 24" width="15" height="15"><path fill="currentColor" d="M16 1H4a2 2 0 0 0-2 2v14h2V3h12V1zm3 4H8a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2zm0 16H8V7h11v14z"/></svg>'; }
function iconEye() { return '<svg viewBox="0 0 24 24" width="15" height="15"><path fill="currentColor" d="M12 5c-7 0-10 7-10 7s3 7 10 7 10-7 10-7-3-7-10-7zm0 12a5 5 0 1 1 0-10 5 5 0 0 1 0 10zm0-2a3 3 0 1 0 0-6 3 3 0 0 0 0 6z"/></svg>'; }
function iconDrag() { return '<svg viewBox="0 0 24 24" width="16" height="16"><path fill="currentColor" d="M9 5a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm0 7a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm0 7a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm6-14a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm0 7a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3zm0 7a1.5 1.5 0 1 1 0-3 1.5 1.5 0 0 1 0 3z"/></svg>'; }
/* ---------------------------------------------------------------
   10. INVOICE LIST
   --------------------------------------------------------------- */
const InvoiceList = {
  init() {
    document.getElementById('searchInput').addEventListener('input', debounce(e => {
      State.listState.search = e.target.value.trim();
      State.listState.page = 1;
      this.render();
    }, 200));
    document.getElementById('filterDate').addEventListener('change', e => {
      State.listState.date = e.target.value; State.listState.page = 1; this.render();
    });
    document.getElementById('filterGst').addEventListener('change', e => {
      State.listState.gst = e.target.value; State.listState.page = 1; this.render();
    });
    document.getElementById('filterStatus').addEventListener('change', e => {
      State.listState.status = e.target.value; State.listState.page = 1; this.render();
    });
    document.getElementById('sortOrder').addEventListener('change', e => {
      State.listState.sort = e.target.value; this.render();
    });
    document.getElementById('pageSizeSelect').value = String(State.listState.pageSize);
    document.getElementById('pageSizeSelect').addEventListener('change', e => {
      State.listState.pageSize = Number(e.target.value) || 10;
      State.listState.page = 1;
      this.render();
    });
  },

  getFiltered() {
    const { search, date, gst, status, sort } = State.listState;
    let list = [...State.invoices];
    if (search) {
      const q = search.toLowerCase();
      list = list.filter(inv =>
        (inv.invoiceNumber || '').toLowerCase().includes(q) ||
        (inv.customerName || '').toLowerCase().includes(q));
    }
    if (date) list = list.filter(inv => inv.invoiceDate === date);
    if (gst === 'gst') list = list.filter(inv => inv.gstEnabled);
    if (gst === 'nogst') list = list.filter(inv => !inv.gstEnabled);
    if (status !== 'all') list = list.filter(inv => inv.status === status);
    list.sort((a, b) => {
      const da = new Date(a.invoiceDate || 0).getTime();
      const db = new Date(b.invoiceDate || 0).getTime();
      return sort === 'newest' ? db - da : da - db;
    });
    return list;
  },

  render(showSkeleton) {
    const tbody = document.getElementById('invoiceTableBody');
    const emptyState = document.getElementById('invoiceEmptyState');

    if (showSkeleton) {
      tbody.innerHTML = Array.from({ length: 5 }).map(() => `
        <tr class="skeleton-row">
          <td><div class="skeleton" style="width:80px"></div></td>
          <td><div class="skeleton" style="width:120px"></div></td>
          <td><div class="skeleton" style="width:70px"></div></td>
          <td><div class="skeleton" style="width:60px"></div></td>
          <td><div class="skeleton" style="width:50px"></div></td>
          <td><div class="skeleton" style="width:70px;margin-left:auto"></div></td>
          <td><div class="skeleton" style="width:80px;margin-left:auto"></div></td>
        </tr>`).join('');
      setTimeout(() => this.render(false), 260);
      return;
    }

    const filtered = this.getFiltered();
    const { page, pageSize, search } = State.listState;
    const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
    const curPage = clamp(page, 1, totalPages);
    State.listState.page = curPage;
    const pageItems = filtered.slice((curPage - 1) * pageSize, curPage * pageSize);

    document.getElementById('invoiceTableWrap').style.display = filtered.length ? '' : (State.invoices.length ? '' : 'none');
    emptyState.style.display = State.invoices.length ? 'none' : 'flex';

    if (!State.invoices.length) {
      tbody.innerHTML = '';
      document.getElementById('pagination').innerHTML = '';
      document.getElementById('paginationSummary').textContent = '';
      bindGlobalActionButtons(document.getElementById('view-invoices'));
      return;
    }

    if (!filtered.length) {
      tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state" style="padding:36px 10px">
        ${iconInvoice()}<h3>No matching invoices</h3><p>Try adjusting your search or filters.</p></div></td></tr>`;
      document.getElementById('paginationSummary').textContent = 'No invoices to show';
    } else {
      tbody.innerHTML = pageItems.map(inv => {
        const t = Calc.totals(inv);
        return `<tr>
          <td><strong>${highlightMatch(inv.invoiceNumber, search)}</strong></td>
          <td>${highlightMatch(inv.customerName || '—', search)}</td>
          <td>${formatDate(inv.invoiceDate)}</td>
          <td><span class="badge ${inv.status}">${inv.status}</span></td>
          <td><span class="badge ${inv.gstEnabled ? 'gst-on' : 'gst-off'}">${inv.gstEnabled ? 'GST' : 'No GST'}</span></td>
          <td class="right">${formatMoney(t.grandTotal, inv.currency)}</td>
          <td class="right">
            <div class="row-actions">
              <button class="icon-action" data-view-inv="${inv.id}" title="View">${iconEye()}</button>
              <button class="icon-action" data-edit-inv="${inv.id}" title="Edit">${iconEdit()}</button>
              <button class="icon-action" data-dup-inv="${inv.id}" title="Duplicate">${iconCopy()}</button>
              <button class="icon-action danger" data-del-inv="${inv.id}" title="Delete">${iconTrash()}</button>
            </div>
          </td>
        </tr>`;
      }).join('');
    }

    if (filtered.length) {
      const rangeStart = (curPage - 1) * pageSize + 1;
      const rangeEnd = Math.min(curPage * pageSize, filtered.length);
      document.getElementById('paginationSummary').textContent =
        `Showing ${rangeStart}–${rangeEnd} of ${filtered.length} invoice${filtered.length === 1 ? '' : 's'}`;
    }

    // Pagination controls
    const pag = document.getElementById('pagination');
    if (totalPages <= 1) { pag.innerHTML = ''; }
    else {
      let html = `<button class="page-btn" data-page="${curPage - 1}" ${curPage === 1 ? 'disabled' : ''}>&larr;</button>`;
      for (let p = 1; p <= totalPages; p++) {
        html += `<button class="page-btn ${p === curPage ? 'active' : ''}" data-page="${p}">${p}</button>`;
      }
      html += `<button class="page-btn" data-page="${curPage + 1}" ${curPage === totalPages ? 'disabled' : ''}>&rarr;</button>`;
      pag.innerHTML = html;
      pag.querySelectorAll('[data-page]').forEach(btn => {
        btn.addEventListener('click', () => { State.listState.page = Number(btn.dataset.page); this.render(); });
      });
    }

    tbody.querySelectorAll('[data-view-inv]').forEach(b => b.addEventListener('click', () => InvoiceViewer.open(b.dataset.viewInv)));
    tbody.querySelectorAll('[data-edit-inv]').forEach(b => b.addEventListener('click', () => Editor.openForEdit(b.dataset.editInv)));
    tbody.querySelectorAll('[data-dup-inv]').forEach(b => b.addEventListener('click', () => InvoiceList.duplicate(b.dataset.dupInv)));
    tbody.querySelectorAll('[data-del-inv]').forEach(b => b.addEventListener('click', () => InvoiceList.remove(b.dataset.delInv)));

    bindGlobalActionButtons(document.getElementById('view-invoices'));
  },

  duplicate(id) {
    const src = State.invoices.find(i => i.id === id);
    if (!src) return;
    const copy = JSON.parse(JSON.stringify(src));
    copy.id = uid('inv');
    copy.invoiceNumber = nextInvoiceNumber();
    copy.status = 'Draft';
    copy.invoiceDate = todayISO();
    copy.createdAt = Date.now();
    copy.updatedAt = Date.now();
    State.invoices.unshift(copy);
    persistInvoices();
    Toast.show(`Duplicated as ${copy.invoiceNumber}`, 'success');
    this.render();
    Dashboard.render();
  },

  remove(id) {
    const inv = State.invoices.find(i => i.id === id);
    if (!inv) return;
    Modal.confirm({
      title: 'Delete invoice?',
      message: `This will permanently delete invoice ${inv.invoiceNumber}. This cannot be undone.`,
      confirmLabel: 'Delete',
      danger: true,
      onConfirm: () => {
        State.invoices = State.invoices.filter(i => i.id !== id);
        persistInvoices();
        Toast.show('Invoice deleted', 'success');
        InvoiceList.render();
        Dashboard.render();
      }
    });
  }
};

function nextInvoiceNumber() {
  const n = State.settings.nextNumber || 1;
  return `${State.settings.invoicePrefix || 'INV'}-${String(n).padStart(3, '0')}`;
}

/* Bind buttons tagged with data-action across whichever view is visible */
function bindGlobalActionButtons(scope) {
  scope.querySelectorAll('[data-action="new-invoice"]').forEach(b => b.onclick = () => Editor.openForNew());
  scope.querySelectorAll('[data-action="export-json"]').forEach(b => b.onclick = () => ImportExport.exportAll());
  scope.querySelectorAll('[data-action="import-json"]').forEach(b => b.onclick = () => ImportExport.triggerImport());
  scope.querySelectorAll('[data-action="clear-all"]').forEach(b => b.onclick = () => ImportExport.clearAll());
  scope.querySelectorAll('[data-view-link]').forEach(b => b.onclick = () => Nav.go(b.dataset.viewLink));
}
/* ---------------------------------------------------------------
   11. EDITOR — create / edit invoice, items, live preview
   --------------------------------------------------------------- */
const Editor = {
  autosaveTimer: null,

  init() {
    const form = document.getElementById('invoiceForm');
    form.addEventListener('input', () => this.onFormInput());
    form.addEventListener('change', () => this.onFormInput());
    form.addEventListener('submit', e => e.preventDefault());

    document.getElementById('f_gstEnabled').addEventListener('change', e => {
      document.getElementById('gstRateRow').style.display = e.target.checked ? 'grid' : 'none';
    });

    document.getElementById('f_imagesEnabled').addEventListener('change', () => {
      // Re-render item rows so the per-item image picker appears/disappears
      setTimeout(() => this.renderItems(), 0);
    });

    document.getElementById('addItemBtn').addEventListener('click', () => this.addItem());

    document.getElementById('f_itemsPerPage').addEventListener('change', e => {
      State.draft.itemsPerPage = e.target.value === 'all' ? 'all' : Number(e.target.value);
      this.updatePreview();
      this.scheduleAutosave();
    });

    document.getElementById('f_repeatHeader').addEventListener('change', e => {
      State.draft.repeatHeader = e.target.checked;
      this.updateRepeatHeaderHint();
      this.updatePreview();
      this.scheduleAutosave();
    });

    document.querySelector('#view-editor [data-action="save-invoice"]').addEventListener('click', () => this.save());
    document.querySelector('#view-editor [data-action="print-invoice"]').addEventListener('click', () => Printer.printInvoice(State.draft));
    document.querySelector('#view-editor [data-action="download-png"]').addEventListener('click', () => PngExporter.download(State.draft));
  },

  blankInvoice() {
    return {
      id: uid('inv'),
      invoiceNumber: nextInvoiceNumber(),
      invoiceDate: todayISO(),
      dueDate: '',
      paymentMethod: 'Cash',
      status: 'Draft',
      currency: State.settings.defaultCurrency,
      customerName: '',
      customerPhone: '',
      customerAddress: '',
      gstEnabled: false,
      gstRate: State.settings.defaultGstRate,
      roundOff: 'yes',
      imagesEnabled: false,
      itemsPerPage: 10,
      repeatHeader: true,
      advancePaid: 0,
      notes: '',
      terms: State.settings.defaultTerms,
      items: [this.blankItem()],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
  },

  blankItem() {
    return { id: uid('itm'), name: '', description: '', qty: 1, unit: 'pcs', rate: 0, discount: 0, gstPercent: '', image: '' };
  },

  openForNew() {
    State.editingId = null;
    State.draft = this.blankInvoice();
    document.getElementById('editorTitle').textContent = 'Create Invoice';
    this.populateForm();
    this.renderItems();
    this.updatePreview();
    Nav.go('editor');
  },

  openForEdit(id) {
    const inv = State.invoices.find(i => i.id === id);
    if (!inv) { Toast.show('Invoice not found', 'error'); return; }
    State.editingId = id;
    State.draft = JSON.parse(JSON.stringify(inv));
    if (!State.draft.itemsPerPage) State.draft.itemsPerPage = 10;
    if (State.draft.repeatHeader === undefined) State.draft.repeatHeader = true;
    document.getElementById('editorTitle').textContent = `Edit Invoice — ${inv.invoiceNumber}`;
    this.populateForm();
    this.renderItems();
    this.updatePreview();
    Nav.go('editor');
  },

  populateForm() {
    const d = State.draft;
    const $ = id => document.getElementById(id);
    $('f_invoiceNumber').value = d.invoiceNumber;
    $('f_invoiceDate').value = d.invoiceDate;
    $('f_dueDate').value = d.dueDate;
    $('f_paymentMethod').value = d.paymentMethod;
    $('f_status').value = d.status;
    $('f_currency').value = d.currency;
    $('f_customerName').value = d.customerName;
    $('f_customerPhone').value = d.customerPhone;
    $('f_customerAddress').value = d.customerAddress;
    $('f_gstEnabled').checked = d.gstEnabled;
    document.getElementById('gstRateRow').style.display = d.gstEnabled ? 'grid' : 'none';
    $('f_gstRate').value = d.gstRate;
    $('f_roundOff').value = d.roundOff;
    $('f_imagesEnabled').checked = d.imagesEnabled;
    $('f_itemsPerPage').value = String(d.itemsPerPage || 10);
    $('f_repeatHeader').checked = d.repeatHeader !== false;
    this.updateRepeatHeaderHint();
    $('f_advancePaid').value = d.advancePaid;
    $('f_notes').value = d.notes;
    $('f_terms').value = d.terms;
    this.clearErrors();
  },

  onFormInput() {
    const d = State.draft;
    const $ = id => document.getElementById(id);
    d.invoiceNumber = $('f_invoiceNumber').value.trim();
    d.invoiceDate = $('f_invoiceDate').value;
    d.dueDate = $('f_dueDate').value;
    d.paymentMethod = $('f_paymentMethod').value;
    d.status = $('f_status').value;
    d.currency = $('f_currency').value;
    d.customerName = $('f_customerName').value;
    d.customerPhone = $('f_customerPhone').value;
    d.customerAddress = $('f_customerAddress').value;
    d.gstEnabled = $('f_gstEnabled').checked;
    d.gstRate = Number($('f_gstRate').value) || 0;
    d.roundOff = $('f_roundOff').value;
    d.imagesEnabled = $('f_imagesEnabled').checked;
    d.advancePaid = Number($('f_advancePaid').value) || 0;
    d.notes = $('f_notes').value;
    d.terms = $('f_terms').value;
    d.updatedAt = Date.now();
    this.updatePreview();
    this.scheduleAutosave();
  },

  scheduleAutosave() {
    const tag = document.getElementById('autosaveStatus');
    tag.textContent = 'Saving…';
    tag.className = 'autosave-status saving';
    clearTimeout(this.autosaveTimer);
    this.autosaveTimer = setTimeout(() => {
      Storage.set(STORAGE_KEYS.draft, { editingId: State.editingId, draft: State.draft });
      tag.textContent = 'Draft saved';
      tag.className = 'autosave-status saved';
    }, 700);
  },

  /* ---------------- ITEMS ---------------- */
  renderItems() {
    const wrap = document.getElementById('itemsList');
    const items = State.draft.items;
    wrap.innerHTML = items.map((item, idx) => this.itemRowHTML(item, idx)).join('');

    wrap.querySelectorAll('.item-row').forEach(row => {
      const idx = Number(row.dataset.idx);

      row.querySelectorAll('[data-field]').forEach(input => {
        input.addEventListener('input', () => {
          const field = input.dataset.field;
          let val = input.value;
          if (['qty', 'rate', 'discount', 'gstPercent'].includes(field)) {
            val = val === '' ? (field === 'gstPercent' ? '' : 0) : Number(val);
          }
          items[idx][field] = val;
          this.updateItemAmountDisplay(row, items[idx]);
          this.updatePreview();
          this.scheduleAutosave();
        });
      });

      row.querySelector('[data-action="dup-item"]').addEventListener('click', () => {
        const copy = JSON.parse(JSON.stringify(items[idx]));
        copy.id = uid('itm');
        items.splice(idx + 1, 0, copy);
        this.renderItems(); this.updatePreview(); this.scheduleAutosave();
      });
      row.querySelector('[data-action="remove-item"]').addEventListener('click', () => {
        if (items.length === 1) { Toast.show('An invoice needs at least one item', 'error'); return; }
        items.splice(idx, 1);
        this.renderItems(); this.updatePreview(); this.scheduleAutosave();
      });

      const imgInput = row.querySelector('[data-field="image"]');
      if (imgInput) {
        imgInput.addEventListener('change', () => {
          const file = imgInput.files[0];
          if (!file) return;
          if (file.size > 3 * 1024 * 1024) { Toast.show('Image too large (max 3MB)', 'error'); return; }
          const reader = new FileReader();
          reader.onload = () => {
            items[idx].image = reader.result;
            row.querySelector('.item-thumb').src = reader.result;
            this.updatePreview();
            this.scheduleAutosave();
          };
          reader.readAsDataURL(file);
        });
      }
      const clearImgBtn = row.querySelector('[data-action="clear-item-image"]');
      if (clearImgBtn) clearImgBtn.addEventListener('click', () => {
        items[idx].image = '';
        row.querySelector('.item-thumb').src = TRANSPARENT_PX;
        this.updatePreview(); this.scheduleAutosave();
      });

      // Drag reorder
      row.setAttribute('draggable', 'true');
      row.addEventListener('dragstart', () => row.classList.add('dragging'));
      row.addEventListener('dragend', () => {
        row.classList.remove('dragging');
        const newOrderIds = [...wrap.querySelectorAll('.item-row')].map(r => r.dataset.id);
        State.draft.items.sort((a, b) => newOrderIds.indexOf(a.id) - newOrderIds.indexOf(b.id));
        this.renderItems(); this.updatePreview(); this.scheduleAutosave();
      });
    });

    wrap.addEventListener('dragover', e => {
      e.preventDefault();
      const dragging = wrap.querySelector('.dragging');
      if (!dragging) return;
      const after = [...wrap.querySelectorAll('.item-row:not(.dragging)')].find(el => {
        const box = el.getBoundingClientRect();
        return e.clientY < box.top + box.height / 2;
      });
      if (after) wrap.insertBefore(dragging, after);
      else wrap.appendChild(dragging);
    });
  },

  itemRowHTML(item, idx) {
    const showImg = State.draft.imagesEnabled;
    return `
    <div class="item-row" data-idx="${idx}" data-id="${item.id}">
      <div class="item-row-head">
        <span class="drag-handle" title="Drag to reorder">${iconDrag()}</span>
        <span class="item-index">${idx + 1}.</span>
        <input class="item-title-input" data-field="name" value="${escapeHtml(item.name)}" placeholder="Product name">
        <div class="item-actions">
          <button type="button" class="icon-action" data-action="dup-item" title="Duplicate item">${iconCopy()}</button>
          <button type="button" class="icon-action danger" data-action="remove-item" title="Remove item">${iconTrash()}</button>
        </div>
      </div>
      <div class="item-body">
        <label class="item-desc">Description
          <input type="text" data-field="description" value="${escapeHtml(item.description)}" placeholder="Optional detail">
        </label>
        <label>Qty
          <input type="number" min="0" step="0.01" data-field="qty" value="${item.qty}">
        </label>
        <label>Unit
          <select data-field="unit">
            ${['pcs','sqft','nos','kg','ltr','box','set','hrs','sft','ft'].map(u => `<option ${item.unit===u?'selected':''}>${u}</option>`).join('')}
          </select>
        </label>
        <label>Rate
          <input type="number" min="0" step="0.01" data-field="rate" value="${item.rate}">
        </label>
        <label>Discount
          <input type="number" min="0" step="0.01" data-field="discount" value="${item.discount}">
        </label>
        <label>GST %
          <input type="number" min="0" step="0.1" data-field="gstPercent" value="${item.gstPercent}" placeholder="${State.draft.gstRate}">
        </label>
        ${showImg ? `
        <label class="item-desc">Product Image
          <div class="item-image-picker">
            <img class="item-thumb" src="${item.image || TRANSPARENT_PX}" alt="">
            <input type="file" accept="image/*" data-field="image">
            <button type="button" class="btn small ghost" data-action="clear-item-image">Clear</button>
          </div>
        </label>` : ''}
        <div class="item-amount-display">
          <span>Line amount (pre-tax)</span>
          <strong>${formatMoney(Calc.itemTaxable(item), State.draft.currency)}</strong>
        </div>
      </div>
    </div>`;
  },

  updateItemAmountDisplay(row, item) {
    const strong = row.querySelector('.item-amount-display strong');
    if (strong) strong.textContent = formatMoney(Calc.itemTaxable(item), State.draft.currency);
  },

  addItem() {
    State.draft.items.push(this.blankItem());
    this.renderItems();
    this.updatePreview();
    this.scheduleAutosave();
    document.getElementById('itemsList').lastElementChild.querySelector('.item-title-input').focus();
  },

  /* ---------------- VALIDATION ---------------- */
  clearErrors() {
    document.querySelectorAll('.field-error').forEach(el => el.classList.remove('field-error'));
    document.querySelectorAll('.error-text').forEach(el => el.remove());
  },
  markError(inputId, message) {
    const el = document.getElementById(inputId);
    el.classList.add('field-error');
    const msg = document.createElement('div');
    msg.className = 'error-text';
    msg.textContent = message;
    el.insertAdjacentElement('afterend', msg);
  },
  validate() {
    this.clearErrors();
    let ok = true;
    const d = State.draft;
    if (!d.invoiceNumber) { this.markError('f_invoiceNumber', 'Invoice number is required'); ok = false; }
    if (!d.invoiceDate) { this.markError('f_invoiceDate', 'Invoice date is required'); ok = false; }
    if (!d.customerName.trim()) { this.markError('f_customerName', 'Customer name is required'); ok = false; }
    if (!d.items.length || d.items.every(i => !i.name.trim())) {
      Toast.show('Add at least one product item with a name', 'error');
      ok = false;
    }
    const dupNumber = State.invoices.find(i => i.invoiceNumber === d.invoiceNumber && i.id !== d.id);
    if (dupNumber) { this.markError('f_invoiceNumber', 'This invoice number is already used'); ok = false; }
    return ok;
  },

  /* ---------------- SAVE ---------------- */
  save() {
    if (!this.validate()) { Toast.show('Please fix the highlighted fields', 'error'); return; }
    const d = State.draft;
    d.updatedAt = Date.now();
    const existingIdx = State.invoices.findIndex(i => i.id === d.id);
    const isNew = existingIdx === -1;
    if (isNew) {
      State.invoices.unshift(d);
      const numPart = parseInt(String(d.invoiceNumber).replace(/\D/g, ''), 10);
      if (!isNaN(numPart) && numPart >= State.settings.nextNumber) {
        State.settings.nextNumber = numPart + 1;
        persistSettings();
      }
    } else {
      State.invoices[existingIdx] = d;
    }
    persistInvoices();
    Storage.remove(STORAGE_KEYS.draft);
    Toast.show(isNew ? 'Invoice created' : 'Invoice updated', 'success');
    State.editingId = d.id;
    document.getElementById('autosaveStatus').textContent = 'Saved';
    document.getElementById('autosaveStatus').className = 'autosave-status saved';
    Dashboard.render();
  },

  updateRepeatHeaderHint() {
    const hint = document.getElementById('repeatHeaderHint');
    if (!hint) return;
    hint.textContent = document.getElementById('f_repeatHeader').checked
      ? 'The company header and customer details repeat at the top of every printed page.'
      : 'The full header appears only on page 1 — later pages show a compact continuation bar instead.';
  },

  /* ---------------- LIVE PREVIEW ---------------- */
  updatePreview() {
    document.getElementById('invoicePreview').innerHTML = InvoiceDoc.renderPagesJoined(State.draft, State.settings);
  }
};

const TRANSPARENT_PX = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBTAA7';
/* ---------------------------------------------------------------
   12. INVOICE DOCUMENT RENDERER
   Builds markup that mirrors the uploaded "Sharp Home Decors"
   tax-invoice template: logo/company header, TAX INVOICE title,
   customer/meta box, itemised table, summary block, amount in
   words, terms & conditions, and a signature footer.

   The product table paginates: each invoice carries its own
   `itemsPerPage` setting (default 10, chosen on the editor's
   preview panel). When the item count exceeds that, the table
   is split across several full "pages" — each repeating the
   company header/customer details, and only the last page
   carrying the totals, amount-in-words, and terms — exactly
   like the uploaded template's "Page 1 of 3 / 2 of 3 / 3 of 3".
   --------------------------------------------------------------- */
const InvoiceDoc = {
  /* Split the item list into pages according to invoice.itemsPerPage */
  paginateItems(items, itemsPerPage) {
    items = items || [];
    if (!itemsPerPage || itemsPerPage === 'all') return [items];
    const n = Number(itemsPerPage) || 10;
    if (items.length === 0) return [[]];
    const pages = [];
    for (let i = 0; i < items.length; i += n) pages.push(items.slice(i, i + n));
    return pages;
  },

  headerHTML(settings) {
    return `
      <div class="doc-header">
        <div class="doc-logo-block">
          ${settings.logo ? `<img src="${settings.logo}" alt="Company logo">` : `<div style="font-weight:800;font-size:20px;color:#3D2314">${escapeHtml(settings.companyName)}</div>`}
          ${settings.companyTagline ? `<div class="doc-tagline">${escapeHtml(settings.companyTagline)}</div>` : ''}
        </div>
        <div class="doc-company">
          <div class="cname">${escapeHtml(settings.companyName)}</div>
          <div class="caddr">${escapeHtml(settings.companyAddress)}</div>
          ${settings.companyPhone ? `<div class="caddr"><strong>Phone:</strong> ${escapeHtml(settings.companyPhone)}</div>` : ''}
        </div>
      </div>
      <div class="doc-title">TAX INVOICE</div>`;
  },

  metaHTML(invoice, settings) {
    return `
      <div class="doc-meta">
        <div class="doc-meta-left">
          <div><span class="lbl">CUSTOMER DETAILS</span></div>
          <div><span class="lbl">Customer Name:</span> ${escapeHtml(invoice.customerName || '—')}</div>
          ${invoice.customerPhone ? `<div><span class="lbl">Phone:</span> ${escapeHtml(invoice.customerPhone)}</div>` : ''}
          ${invoice.customerAddress ? `<div><span class="lbl">Address:</span> ${escapeHtml(invoice.customerAddress)}</div>` : ''}
        </div>
        <div class="doc-meta-right">
          <div><span class="lbl">Invoice No:</span> ${escapeHtml(invoice.invoiceNumber)}</div>
          <div><span class="lbl">Date:</span> ${formatDate(invoice.invoiceDate, settings.dateFormat)}</div>
          ${invoice.dueDate ? `<div><span class="lbl">Due:</span> ${formatDate(invoice.dueDate, settings.dateFormat)}</div>` : ''}
          <div><span class="lbl">Payment:</span> ${escapeHtml(invoice.paymentMethod)}</div>
          <div><span class="lbl">Status:</span> ${escapeHtml(invoice.status)}</div>
        </div>
      </div>`;
  },

  rowHTML(item, serialNo, invoice, showImages) {
    const amount = Calc.itemTaxable(item);
    const cur = invoice.currency;
    return `
      <tr>
        <td class="center">${serialNo}</td>
        <td>
          <div class="prod-name">${escapeHtml(item.name || 'Untitled item')}</div>
          ${item.description ? `<div class="prod-desc">${escapeHtml(item.description)}</div>` : ''}
        </td>
        ${showImages ? `<td class="center">${item.image ? `<img class="prod-img" src="${item.image}" alt="">` : ''}</td>` : ''}
        <td class="center">${formatQty(item.qty)} ${escapeHtml(item.unit || '')}</td>
        <td class="right">${formatMoney(item.rate, cur)}</td>
        <td class="right">${formatMoney(amount, cur)}</td>
      </tr>`;
  },

  tableHTML(rowsHtml, showImages) {
    return `
      <table class="doc-table">
        <thead>
          <tr>
            <th class="center" style="width:36px">S.No.</th>
            <th>Description</th>
            ${showImages ? '<th class="center" style="width:60px">Image</th>' : ''}
            <th class="center" style="width:70px">Qty</th>
            <th class="right" style="width:90px">Unit Price</th>
            <th class="right" style="width:100px">Amount</th>
          </tr>
        </thead>
        <tbody>${rowsHtml || `<tr><td colspan="${showImages ? 6 : 5}" class="center" style="color:#888;padding:16px">No items added</td></tr>`}</tbody>
      </table>`;
  },

  summaryHTML(invoice, settings) {
    const t = Calc.totals(invoice);
    const cur = invoice.currency || settings.defaultCurrency;
    const termsLines = (invoice.terms || '').split('\n').map(l => l.trim()).filter(Boolean);
    return `
      <div class="doc-summary">
        <table>
          <tr><td class="k">Subtotal</td><td class="v">${formatMoney(t.subtotalGross, cur)}</td></tr>
          ${t.discountTotal > 0 ? `<tr><td class="k">Discount</td><td class="v">- ${formatMoney(t.discountTotal, cur)}</td></tr>` : ''}
          ${invoice.gstEnabled ? `
          <tr><td class="k">CGST (${(invoice.gstRate / 2).toFixed(1)}%)</td><td class="v">${formatMoney(t.cgst, cur)}</td></tr>
          <tr><td class="k">SGST (${(invoice.gstRate / 2).toFixed(1)}%)</td><td class="v">${formatMoney(t.sgst, cur)}</td></tr>` : ''}
          ${t.roundOffAmt !== 0 ? `<tr><td class="k">Round Off</td><td class="v">${t.roundOffAmt > 0 ? '+' : ''}${formatMoney(t.roundOffAmt, cur)}</td></tr>` : ''}
          <tr class="grand"><td class="k">Grand Total</td><td class="v">${formatMoney(t.grandTotal, cur)}</td></tr>
          ${t.advancePaid > 0 ? `<tr><td class="k">Advance Paid</td><td class="v">- ${formatMoney(t.advancePaid, cur)}</td></tr>
          <tr><td class="k"><strong>Balance Due</strong></td><td class="v"><strong>${formatMoney(t.balanceDue, cur)}</strong></td></tr>` : ''}
        </table>
      </div>

      <div class="doc-words"><strong>Grand Total in words:</strong> ${escapeHtml(amountInWords(t.grandTotal, cur).toUpperCase())}</div>

      ${invoice.notes ? `<div class="doc-notes"><strong>Notes:</strong> ${escapeHtml(invoice.notes)}</div>` : ''}

      ${termsLines.length ? `
      <div class="doc-terms">
        <h4>TERMS AND CONDITIONS</h4>
        <ol>${termsLines.map(l => `<li>${escapeHtml(l)}</li>`).join('')}</ol>
      </div>` : ''}`;
  },

  footerHTML(pageNum, totalPages, isLast) {
    return `
      <div class="doc-footer">
        <div class="doc-page">Page ${pageNum} of ${totalPages}</div>
        ${isLast ? `<div class="doc-sign"><div class="line"></div>Authorized Signatory</div>` : '<div></div>'}
      </div>`;
  },

  /* Compact bar shown on page 2+ instead of the full header when "repeat header" is off */
  continuedBarHTML(invoice, settings, pageNum, totalPages) {
    return `
      <div class="doc-continued-bar">
        <strong>${escapeHtml(settings.companyName)}</strong>
        <span>Invoice ${escapeHtml(invoice.invoiceNumber)} &middot; ${escapeHtml(invoice.customerName || '—')} &middot; continued (page ${pageNum} of ${totalPages})</span>
      </div>`;
  },

  /* Build an array of complete, ready-to-render page HTML strings */
  renderPages(invoice, settings) {
    const showImages = !!invoice.imagesEnabled;
    const repeatHeader = invoice.repeatHeader !== false; // default true — keeps prior behaviour unless explicitly turned off
    const chunks = this.paginateItems(invoice.items, invoice.itemsPerPage);
    const totalPages = chunks.length;
    const stamp = ['Paid', 'Cancelled', 'Pending'].includes(invoice.status)
      ? `<div class="doc-status-stamp ${invoice.status}">${invoice.status.toUpperCase()}</div>` : '';

    let serial = 0;
    return chunks.map((chunk, i) => {
      const pageNum = i + 1;
      const isLast = pageNum === totalPages;
      const isFirst = pageNum === 1;
      const rowsHtml = chunk.map(item => { serial++; return this.rowHTML(item, serial, invoice, showImages); }).join('');
      const showFullHeader = isFirst || repeatHeader;
      return `<div class="invoice-doc">
        <div class="doc-corner"></div>
        ${stamp}
        ${showFullHeader ? `${this.headerHTML(settings)}${this.metaHTML(invoice, settings)}` : this.continuedBarHTML(invoice, settings, pageNum, totalPages)}
        ${this.tableHTML(rowsHtml, showImages)}
        ${isLast ? this.summaryHTML(invoice, settings) : ''}
        ${this.footerHTML(pageNum, totalPages, isLast)}
      </div>`;
    });
  },

  /* All pages stacked, ready to drop into the preview panel, print area, or a PNG export container */
  renderPagesJoined(invoice, settings) {
    return this.renderPages(invoice, settings)
      .map(pageHtml => `<div class="doc-page-sheet">${pageHtml}</div>`)
      .join('');
  }
};

function formatQty(q) {
  const n = Number(q) || 0;
  return Number.isInteger(n) ? String(n) : n.toFixed(2);
}

