/* ---------------------------------------------------------------
   15. PNG EXPORT — pure vanilla technique using SVG <foreignObject>
   rendered to a <canvas>. No external screenshot library.
   --------------------------------------------------------------- */
const INLINE_PROPS = [
  'color', 'background', 'background-color', 'background-image', 'background-position', 'background-size', 'background-repeat',
  'font-family', 'font-size', 'font-weight', 'font-style', 'line-height', 'text-align', 'text-decoration', 'text-transform',
  'letter-spacing', 'white-space', 'vertical-align',
  'border', 'border-top', 'border-right', 'border-bottom', 'border-left', 'border-color', 'border-style', 'border-width', 'border-radius', 'border-collapse', 'border-spacing',
  'padding', 'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
  'margin', 'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
  'width', 'height', 'max-width', 'max-height', 'min-width', 'min-height',
  'display', 'flex-direction', 'justify-content', 'align-items', 'gap', 'flex', 'flex-wrap',
  'position', 'top', 'left', 'right', 'bottom', 'box-sizing', 'box-shadow',
  'object-fit', 'overflow', 'opacity', 'transform', 'list-style', 'z-index'
];

function inlineStylesRecursive(el) {
  const computed = window.getComputedStyle(el);
  let cssText = '';
  INLINE_PROPS.forEach(prop => {
    const val = computed.getPropertyValue(prop);
    if (val) cssText += `${prop}:${val};`;
  });
  el.setAttribute('style', cssText);
  Array.from(el.children).forEach(child => inlineStylesRecursive(child));
}

function waitForImages(root) {
  const imgs = Array.from(root.querySelectorAll('img'));
  return Promise.all(imgs.map(img => {
    if (img.complete) return Promise.resolve();
    return new Promise(res => { img.onload = res; img.onerror = res; });
  }));
}

const PngExporter = {
  async download(invoice) {
    if (!invoice) return;
    const overlay = document.getElementById('loadingOverlay');
    overlay.style.display = 'flex';
    const wrapper = document.createElement('div');
    wrapper.style.position = 'fixed';
    wrapper.style.left = '-10000px';
    wrapper.style.top = '0';
    wrapper.style.background = '#ffffff';
    wrapper.innerHTML = `<div class="doc-export-stack">${InvoiceDoc.renderPagesJoined(invoice, State.settings)}</div>`;
    document.body.appendChild(wrapper);
    const docEl = wrapper.querySelector('.doc-export-stack');

    try {
      await waitForImages(docEl);
      inlineStylesRecursive(docEl);

      const rect = docEl.getBoundingClientRect();
      const w = Math.ceil(rect.width);
      const h = Math.ceil(rect.height);

      const serializer = new XMLSerializer();
      const xml = serializer.serializeToString(docEl).replace(/xmlns=""/g, '');

      const svgString =
        `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
          <foreignObject width="100%" height="100%">
            <div xmlns="http://www.w3.org/1999/xhtml">${xml}</div>
          </foreignObject>
        </svg>`;

      const svgDataUrl = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgString);

      const img = new Image();
      const scale = 2; // high resolution multiplier
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
        img.src = svgDataUrl;
      });

      const canvas = document.createElement('canvas');
      canvas.width = w * scale;
      canvas.height = h * scale;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.scale(scale, scale);
      ctx.drawImage(img, 0, 0, w, h);

      const pngUrl = canvas.toDataURL('image/png', 1.0);
      const a = document.createElement('a');
      a.href = pngUrl;
      a.download = `Invoice-${invoice.invoiceNumber || 'draft'}.png`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      Toast.show('Invoice downloaded as PNG', 'success');
    } catch (err) {
      console.error('PNG export failed', err);
      Toast.show('Could not generate PNG in this browser', 'error');
    } finally {
      wrapper.remove();
      overlay.style.display = 'none';
    }
  }
};
/* ---------------------------------------------------------------
   16. IMPORT / EXPORT
   --------------------------------------------------------------- */
const ImportExport = {
  exportAll() {
    const payload = {
      app: 'InvoiceForge',
      version: 1,
      exportedAt: new Date().toISOString(),
      settings: State.settings,
      invoices: State.invoices
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `invoiceforge-backup-${todayISO()}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    Toast.show('Invoices exported', 'success');
  },

  triggerImport() {
    document.getElementById('importFileInput').click();
  },

  handleFile(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      let data;
      try {
        data = JSON.parse(reader.result);
      } catch (e) {
        Toast.show('That file is not valid JSON', 'error');
        return;
      }
      let incomingInvoices = [];
      let incomingSettings = null;
      if (Array.isArray(data)) incomingInvoices = data;
      else if (data && Array.isArray(data.invoices)) {
        incomingInvoices = data.invoices;
        if (data.settings && typeof data.settings === 'object') incomingSettings = data.settings;
      } else {
        Toast.show('This JSON file does not contain any invoices', 'error');
        return;
      }
      const validInvoices = incomingInvoices.filter(i => i && typeof i === 'object' && i.invoiceNumber);
      if (!validInvoices.length) {
        Toast.show('No valid invoices found in file', 'error');
        return;
      }
      Modal.confirm({
        title: 'Import invoices?',
        message: `This file contains ${validInvoices.length} invoice(s)${incomingSettings ? ' and a company profile' : ''}. They will be merged into your current data (${State.invoices.length} existing).`,
        confirmLabel: 'Import',
        onConfirm: () => {
          const existingIds = new Set(State.invoices.map(i => i.id));
          validInvoices.forEach(inv => {
            if (!inv.id || existingIds.has(inv.id)) inv.id = uid('inv');
            if (!inv.status) inv.status = 'Draft';
            if (!inv.items) inv.items = [];
            if (!inv.createdAt) inv.createdAt = Date.now();
            inv.updatedAt = Date.now();
            existingIds.add(inv.id);
            State.invoices.unshift(inv);
          });
          persistInvoices();
          if (incomingSettings) {
            State.settings = Object.assign({}, DEFAULT_SETTINGS, incomingSettings);
            persistSettings();
          }
          Toast.show(`Imported ${validInvoices.length} invoice(s)`, 'success');
          Dashboard.render();
          InvoiceList.render();
          Settings.render();
        }
      });
    };
    reader.readAsText(file);
  },

  clearAll() {
    Modal.confirm({
      title: 'Erase all data?',
      message: 'This permanently deletes every invoice and resets settings to defaults on this device. This cannot be undone.',
      confirmLabel: 'Erase everything',
      danger: true,
      onConfirm: () => {
        State.invoices = [];
        State.settings = Object.assign({}, DEFAULT_SETTINGS);
        Storage.remove(STORAGE_KEYS.invoices);
        Storage.remove(STORAGE_KEYS.settings);
        Storage.remove(STORAGE_KEYS.draft);
        Toast.show('All data erased', 'success');
        Dashboard.render();
        InvoiceList.render();
        Settings.render();
      }
    });
  }
};

/* ---------------------------------------------------------------
   17. SETTINGS VIEW
   --------------------------------------------------------------- */
const Settings = {
  init() {
    document.getElementById('saveSettingsBtn').addEventListener('click', () => this.save());
    document.getElementById('s_logoInput').addEventListener('change', e => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        document.getElementById('logoPreview').src = reader.result;
        this._pendingLogo = reader.result;
      };
      reader.readAsDataURL(file);
    });
    document.getElementById('clearLogoBtn').addEventListener('click', () => {
      this._pendingLogo = '';
      document.getElementById('logoPreview').src = TRANSPARENT_PX;
    });
  },

  render() {
    const s = State.settings;
    const $ = id => document.getElementById(id);
    $('s_companyName').value = s.companyName;
    $('s_companyAddress').value = s.companyAddress;
    $('s_companyPhone').value = s.companyPhone;
    $('s_companyTagline').value = s.companyTagline;
    $('s_invoicePrefix').value = s.invoicePrefix;
    $('s_nextNumber').value = s.nextNumber;
    $('s_defaultGstRate').value = s.defaultGstRate;
    $('s_dateFormat').value = s.dateFormat;
    $('s_defaultCurrency').value = s.defaultCurrency;
    $('s_defaultTerms').value = s.defaultTerms;
    $('logoPreview').src = s.logo || TRANSPARENT_PX;
    this._pendingLogo = undefined;
    document.getElementById('settingsSavedTag').textContent = '';
  },

  save() {
    const $ = id => document.getElementById(id);
    const s = State.settings;
    s.companyName = $('s_companyName').value.trim() || DEFAULT_SETTINGS.companyName;
    s.companyAddress = $('s_companyAddress').value.trim();
    s.companyPhone = $('s_companyPhone').value.trim();
    s.companyTagline = $('s_companyTagline').value.trim();
    s.invoicePrefix = $('s_invoicePrefix').value.trim() || 'INV';
    s.nextNumber = Math.max(1, Number($('s_nextNumber').value) || 1);
    s.defaultGstRate = Number($('s_defaultGstRate').value) || 0;
    s.dateFormat = $('s_dateFormat').value;
    s.defaultCurrency = $('s_defaultCurrency').value;
    s.defaultTerms = $('s_defaultTerms').value;
    if (this._pendingLogo !== undefined) s.logo = this._pendingLogo;
    persistSettings();
    const tag = document.getElementById('settingsSavedTag');
    tag.textContent = 'Settings saved ✓';
    tag.className = 'autosave-status saved';
    Toast.show('Settings saved', 'success');
    Dashboard.render();
  }
};

/* ---------------------------------------------------------------
   18. KEYBOARD SHORTCUTS
   --------------------------------------------------------------- */
document.addEventListener('keydown', e => {
  const tag = (document.activeElement && document.activeElement.tagName) || '';
  const typing = ['INPUT', 'TEXTAREA', 'SELECT'].includes(tag);
  if (e.key === '/' && !typing) {
    if (State.currentView === 'invoices') { e.preventDefault(); document.getElementById('searchInput').focus(); }
  }
  if ((e.key === 'n' || e.key === 'N') && !typing && !e.metaKey && !e.ctrlKey) {
    e.preventDefault();
    Editor.openForNew();
  }
  if (e.key === 'Escape') Modal.close();
});

